from collections import Counter
def denoise(grid, min_size=3):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or grid[i][j]==bg: continue
            c=grid[i][j]; stack=[(i,j)]; seen[i][j]=True; comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                        seen[ny][nx]=True; stack.append((ny,nx))
            if len(comp)>=min_size:
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                for y in range(min(ys),max(ys)+1):
                    for x in range(min(xs),max(xs)+1):
                        out[y][x]=c
    return out

