from collections import Counter

def background(grid):
    """The most common cell color."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, color):
    """The 4-connected components of one color as cell lists."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and not seen[i][j]:
                stack = [(i, j)]; seen[i][j] = True; comp = []
                while stack:
                    y, x = stack.pop(); comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and not seen[ny][nx]:
                            seen[ny][nx] = True; stack.append((ny, nx))
                comps.append(comp)
    return comps

def fill_bbox(grid, cells, color=None):
    """A copy of the grid with the bounding rectangle of cells filled with color (default: the cells' own color)."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ys = [y for y, _ in cells]; xs = [x for _, x in cells]
    c = color if color is not None else grid[cells[0][0]][cells[0][1]]
    for y in range(min(ys), max(ys) + 1):
        for x in range(min(xs), max(xs) + 1):
            out[y][x] = c
    return out

def denoise_to_rectangles(grid, min_size=3):
    """Keep only components of at least min_size cells; each becomes its solid bounding rectangle; other cells become the background."""
    bg = background(grid)
    out = [[bg] * len(row) for row in grid]
    for color in {v for row in grid for v in row} - {bg}:
        for comp in components(grid, color):
            if len(comp) >= min_size:
                out = fill_bbox(out, comp, color)
    return out
